-- ============================================
-- LUMA — Thème 4 : LONG 1/3 x4 — Une correspondance ratée avec plusieurs obstacles
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent de la compagnie", "staff": "le personnel", "gate_agent": "l''agent de porte"}, "start_node": "n1", "nodes": {"n1": {"speaker": "announcement", "text": "Attention, flight 118 has been delayed by 90 minutes due to a mechanical issue.", "text_fr": "Attention, le vol 118 est retardé de 90 minutes en raison d''un problème mécanique.", "choices": [{"text": "(Do the mental math — this will make you miss your connection.)", "text_fr": "(Fais le calcul mental — ça va te faire rater ta correspondance.)", "next": "n2"}, {"text": "(Head to the gate desk immediately to ask about rebooking.)", "text_fr": "(Va au comptoir de porte immédiatement pour demander une reréservation.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You realize your connection has only a 45-minute layover — this delay will make you miss it.)", "text_fr": "(Vous réalisez que votre correspondance n''a que 45 minutes d''escale — ce retard vous la fera rater.)", "choices": [{"text": "(Approach the gate agent calmly to explain the situation.)", "text_fr": "(Approche l''agent de porte calmement pour expliquer la situation.)", "next": "n3"}]}, "n2b": {"speaker": "agent", "text": "I see you have a tight connection — let me check what we can do.", "text_fr": "Je vois que vous avez une correspondance serrée — laissez-moi vérifier ce qu''on peut faire.", "choices": [{"text": "Thank you, I appreciate you looking into it.", "text_fr": "Merci, j''apprécie que vous vérifiiez.", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "Unfortunately, with this delay, you will miss your connecting flight.", "text_fr": "Malheureusement, avec ce retard, vous allez rater votre vol de correspondance.", "choices": [{"text": "Okay — what are my options for getting to my destination?", "text_fr": "D''accord — quelles sont mes options pour arriver à destination ?", "next": "n4"}, {"text": "This is frustrating, but let''s figure out a solution together.", "text_fr": "C''est frustrant, mais trouvons une solution ensemble.", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "There''s a later flight, but it''s fully booked. There''s also a route through a different city.", "text_fr": "Il y a un vol plus tard, mais il est complet. Il y a aussi un itinéraire via une autre ville.", "choices": [{"text": "Tell me more about the alternate route.", "text_fr": "Dites-m''en plus sur l''itinéraire alternatif.", "next": "n5"}, {"text": "Could I be added to a waitlist for the later flight instead?", "text_fr": "Je pourrais être ajouté sur liste d''attente pour le vol plus tard plutôt ?", "next": "n5b"}]}, "n5": {"speaker": "agent", "text": "It goes through Denver, arriving about 4 hours later than planned, but it''s confirmed.", "text_fr": "Ça passe par Denver, arrivant environ 4 heures plus tard que prévu, mais c''est confirmé.", "choices": [{"text": "Let''s do that then, at least it''s guaranteed.", "text_fr": "Faisons ça alors, au moins c''est garanti.", "next": "n6"}]}, "n5b": {"speaker": "agent", "text": "I can do that, but I can''t guarantee a seat will open up.", "text_fr": "Je peux faire ça, mais je ne peux pas garantir qu''une place se libère.", "choices": [{"text": "That''s too risky, let''s go with the confirmed alternate route instead.", "text_fr": "C''est trop risqué, allons-y avec l''itinéraire alternatif confirmé plutôt.", "next": "n5"}]}, "n6": {"speaker": "agent", "text": "Great, I''ll get you booked on that route through Denver.", "text_fr": "Super, je vous réserve sur cet itinéraire via Denver.", "choices": [{"text": "Thank you, I really appreciate your help with this.", "text_fr": "Merci, j''apprécie vraiment votre aide.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(You board the delayed flight, arrive in Denver, and rush to find your next gate.)", "text_fr": "(Vous embarquez sur le vol retardé, arrivez à Denver, et vous précipitez pour trouver votre prochaine porte.)", "choices": [{"text": "(Check the departure boards for your gate number.)", "text_fr": "(Vérifie les panneaux de départ pour ton numéro de porte.)", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(The gate has changed at the last minute — it''s now on the other side of the terminal.)", "text_fr": "(La porte a changé à la dernière minute — elle est maintenant de l''autre côté du terminal.)", "choices": [{"text": "(Ask a staff member for the fastest route there.)", "text_fr": "(Demande à un membre du personnel le chemin le plus rapide.)", "next": "n9"}, {"text": "(Follow the signs and hurry there yourself.)", "text_fr": "(Suis les panneaux et dépêche-toi toi-même.)", "next": "n9b"}]}, "n9": {"speaker": "staff", "text": "Take the moving walkway to your left, it''ll save you time.", "text_fr": "Prenez le tapis roulant sur votre gauche, ça vous fera gagner du temps.", "choices": [{"text": "Thank you so much, I''ll hurry there now.", "text_fr": "Merci beaucoup, je m''y dépêche.", "next": "n10"}]}, "n9b": {"speaker": "you_thought", "text": "(You navigate quickly but nearly go the wrong way at a confusing junction.)", "text_fr": "(Vous naviguez rapidement mais faillissez vous tromper de direction à un carrefour confus.)", "choices": [{"text": "(Double back quickly after realizing the mistake.)", "text_fr": "(Fais rapidement demi-tour après avoir réalisé l''erreur.)", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(You arrive at the gate, breathless, just as final boarding is being called.)", "text_fr": "(Vous arrivez à la porte, essoufflé, juste au moment où l''embarquement final est annoncé.)", "choices": [{"text": "(Show your boarding pass, relieved to have made it.)", "text_fr": "(Montre ta carte d''embarquement, soulagé d''avoir réussi.)", "next": "n11"}]}, "n11": {"speaker": "gate_agent", "text": "Just made it! We were about to close the doors.", "text_fr": "Vous y êtes arrivé juste à temps ! On était sur le point de fermer les portes.", "choices": [{"text": "Thank you, what a stressful journey that was.", "text_fr": "Merci, quel voyage stressant.", "next": "n12"}]}, "n12": {"speaker": "gate_agent", "text": "I bet! Well, welcome aboard, take a seat and relax now.", "text_fr": "J''imagine ! Bon, bienvenue à bord, asseyez-vous et détendez-vous maintenant.", "choices": [{"text": "(Sit down and finally exhale, grateful it all worked out.)", "text_fr": "(T''assois et souffles enfin, reconnaissant que tout se soit arrangé.)", "next": "end_madeit"}]}, "end_madeit": {"speaker": "you_thought", "text": "(Despite every obstacle, you made it to your final destination.)", "text_fr": "(Malgré tous les obstacles, vous êtes arrivé à votre destination finale.)", "end": true, "ending_label": "Correspondance ratée surmontée avec succès 🏃✈️🎉"}}}'::jsonb, is_playable = true
where title = 'Une correspondance ratée avec plusieurs obstacles'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
